def shell(title,body,base='',lang='en'):
 return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} · Persian Rug Motifs</title><link rel="stylesheet" href="{base}style.css"></head><body><a class="skip" href="#content">Skip to content</a><header><a class="brand" href="{base}index.html">Persian Rug Motifs</a><a href="{base}presentation.html">繁體中文簡報</a><a href="{base}sources.html">Sources</a><a href="{base}glossary.html">Glossary</a><a href="{base}workflow.html">Workflow</a><a href="{base}checking-log.html">Checking log</a></header><main id="content">{body}</main><footer>Public-source learning Wiki · Pegah Iloukhani · 11457091 · {DATE}<br>Chinese terminology and translation have not been reviewed by a human specialist. <a href="{base}images.html">Image register</a> · <a href="{base}AGENTS.md">Editorial rules</a></footer></body></html>'''
def refs(ids,base=''):
 return '<div class="refs">'+''.join(f'<a href="{base}sources/{x.split("-")[0]}.html#{x}">{x}</a>' for x in dict.fromkeys(ids))+'</div>'
def renderclaim(c,base=''):
 return f'<div class="claim"><span class="tag">{c["label"]}</span>{esc(c["text"])}{refs(c["refs"],base)}</div>'

