def art(i):
 x=images[i]; return f'<figure><img class="art" src="{x["file"]}" alt="{x["alt"]}"><figcaption>{esc(x["title"])}. {esc(x["museum"])} · {x["number"]}. {esc(x["credit"])}. {x["licence"]}. <a href="images.html#{x["id"]}">Credit / 圖片來源</a></figcaption></figure>'

for p in wiki:
 content=f'<p class="eyebrow">Linked Wiki / {p["slug"]}</p><h1>{p["title"]}</h1><p class="sub">{p["subtitle"]}</p>'
 if p['slug'] in ['boteh','herati','shah-abbasi','islimi','toranj-lachak','structure']:
  content+='<div class="hero"><div>'+diagram(p['slug'])+'</div><div class="note">Start with shape and arrangement. Then ask which source supports the historical claim.<p>Chinese names are descriptive teaching labels, not a claim of standardized museum terminology.</p><a href="glossary.html">Open the glossary</a></div></div>'
 for s in p['sections']: content+='<h2>'+s['title']+'</h2>'+''.join(renderclaim(c) for c in s['claims'])
 if p['slug']=='islimi': content+=art(0)
 content+='<h2>Sources and related pages</h2>'+refs([r for s in p['sections'] for c in s['claims'] for r in c['refs']])+'<p class="backlinks">'+''.join(f'<a href="{q["slug"]}.html">{q["title"]}</a>' for q in wiki if q!=p)+'</p><p><a href="glossary.html">Glossary</a> · <a href="sources.html">Source register</a></p>'
 save(p['slug']+'.html',shell(p['title'],content))

save('index.html',shell('Forms, context, and meanings','<div class="hero"><div><p class="eyebrow">An evidence-led learning Wiki</p><h1>Persian Rug Motifs</h1><p class="sub">Forms, context, and meanings.</p><p>Learn to describe what you see, follow the evidence, and leave uncertainty visible. Five motif and composition topics for beginners.</p><a class="button" href="presentation.html">Start the Traditional Chinese lesson</a><p>15 teaching slides + 3 workflow appendices.</p></div>'+art(0)+'</div><h2>Choose a starting point</h2><div class="grid">'+''.join(f'<a class="card" href="{p["slug"]}.html"><h3>{p["title"]}</h3>{p["subtitle"]}</a>' for p in wiki)+'</div><h2>How to use this Wiki</h2><p>Each labelled claim links to a source-note excerpt ID. Notes are short paraphrases with locators and limitations. This is a curated, AI-assisted static knowledge base, not a live chatbot or a trained model.</p><div class="grid"><a class="card" href="sources.html">Read the 10 source notes</a><a class="card" href="workflow.html">Follow the research loop</a><a class="card" href="checking-log.html">Inspect the actual checking log</a></div><p class="note">No personal photos, Rug 42, stories, prices or purchasing recommendations are included. Chinese translation is unreviewed. Image rights are checked independently from public access to text.</p>'))

for s in sources:
 supported=[p for p in wiki if any(r.startswith(s['id']+'-') for section in p['sections'] for c in section['claims'] for r in c['refs'])]
 body=f'<p class="eyebrow">Source note {s["id"]}</p><h1>{esc(s["citation"])}</h1><p><a href="{esc(s["url"])}">Open public source</a></p><p>Accessed {DATE} · {s["type"]}</p><h2>Credibility</h2><p>{esc(s["credibility"])}</p><h2>Limitations</h2><p>{esc(s["limitations"])}</p><h2>Evidence notes</h2><p>Excerpt IDs identify our concise paraphrase notes, not verbatim quotations. Read the linked original for context.</p>'
 for e in s['excerpts']: body+=f'<section id="{e["id"]}" class="card"><h3>{e["id"]}</h3><p>{esc(e["text"])}</p><p class="caption">Locator in original: {esc(e["locator"])}</p></section>'
 body+='<h2>Supports these Wiki pages</h2><p class="backlinks">'+''.join(f'<a href="../{p["slug"]}.html">{p["title"]}</a>' for p in supported)+'</p><p><a href="../sources.html">All sources</a> · <a href="../glossary.html">Glossary</a></p>'
 save('sources/'+s['id']+'.html',shell(s['id'],body,'../'))
save('sources.html',shell('Source register','<p class="eyebrow">10 ingested public records</p><h1>Source register</h1><p>Five independently accessible sources are required. Nine full public records and one limited indexed museum description are represented here. The ten notes are separate documents, not ten independent confirmations of every claim.</p>'+''.join(f'<article class="card"><h2><a href="sources/{s["id"]}.html">{s["id"]} · {esc(s["citation"])}</a></h2><p>{s["type"]} · {s["accessed"]}</p><p>{esc(s["limitations"])}</p></article>' for s in sources)))

gloss=[('Motif','A single decorative unit.','S01-E1'),('Pattern','An arrangement or repeat of units.','S01-E1'),('Composition / design','The overall arrangement across the rug.','S01-E1'),('Field / matn / متن','The area enclosed by borders.','S01-E1'),('Main border / minor border / guard','The broad border stripe, narrower accompanying stripes, and separating bands.','S01-E1'),('Palmette','A stylized fan-like flower.','S01-E3'),('Rosette','A flower-like unit viewed frontally.','S01-E2'),('Warp / weft / pile','Lengthwise threads, crosswise threads, and projecting knot ends.','S06-E1'),('Knot density','Number of knots for a stated length or area; record the unit.','S06-E1'),('Provenance','The recorded history of ownership, including gaps.','S07-E3'),('Attribution','A documented assignment of origin or date, which can remain provisional.','S03-E1'),('Boteh / Herati / Shah Abbasi / Islimi / Toranj–Lachak','Use the five linked topic pages for Persian names and provisional Chinese labels.','S01-E2')]
save('glossary.html',shell('Glossary','<h1>Glossary</h1>'+''.join(f'<section class="claim" id="term-{i}"><h3>{a}</h3><span class="tag">Observation / terminology</span><p>{b}</p>{refs([c])}</section>' for i,(a,b,c) in enumerate(gloss))+'<h2>Explore the terms in context</h2><p class="backlinks">'+''.join(f'<a href="{p["slug"]}.html">{p["title"]}</a>' for p in wiki)+'</p>'))
save('images.html',shell('Image register','<h1>Image register</h1><p>Only the two verified public-domain museum photographs below are embedded. No museum photograph is generated or altered. Original schematics simplify structure and are not historical evidence.</p>'+''.join(f'<section id="{x["id"]}"><h2>{x["id"]} · {x["title"]}</h2>{art(i)}<p><a href="{x["source"]}">Museum object and Public Domain label</a> · accessed {DATE}</p><p>Local asset: {x["file"]}. Display: scaled without distortion; no crop. See assets/museum-metadata.json for API permission metadata.</p></section>' for i,x in enumerate(images))+'<h2>Original diagrams</h2><p>D01–D06: schematic boteh, Herati, palmette, islimi, medallion/corners and rug structure. Created in SVG for this project, based on the cited terminology in S01 and S02. They are not reproductions of museum diagrams. These project-authored schematics are released under CC0.</p><h2>Link-only references</h2><p>V&A Ardabil images are copyright-labelled: <a href="https://www.vam.ac.uk/articles/the-ardabil-carpet">view on the museum website</a>. Royal Collection images are not embedded. No personal photographs are used.</p>'))

workflow='''<h1>From sources to a lesson</h1><p>This execution used an LLM-assisted editorial loop and a reproducible static compiler. It did not run an autonomous multi-agent system or a vector database.</p><div class="flow"><span>1. Public source screening</span><span>2. Evidence notes / excerpt IDs</span><span>3. Linked English Wiki</span><span>4. Claim and rights review</span><span>5. Approved outline</span><span>6. Chinese teaching slides</span><span>7. HTML / browser checks</span></div><h2>Revision paths</h2><ul><li>Unsupported historical claim: return to the original source. Remove it or mark uncertainty if support is insufficient.</li><li>Terminology mismatch: return to the Wiki definition before translating again.</li><li>Wrong attribution or image rights: reject the asset before layout. Use a permitted substitute or a link.</li><li>Broken anchor or layout: repair the compiler or navigation, rebuild, then rerun checks.</li></ul><h2>Stopping conditions</h2><p>At least five ingested sources, seven content pages, traceable slide references and exactly 18 slides. Structural checks must pass. No known critical navigation failures. After three unsuccessful revisions of a claim, mark it unresolved and request human review rather than inventing an answer. Chinese human review remains a stated limitation.</p><h2>Reusable retrieval output</h2><p><a href="data/sources.json">sources.json</a> retains stable evidence IDs; <a href="data/wiki.json">wiki.json</a> stores labelled claims. A future Rug Detective retrieval system can consume these files, but must retain the human motif-confirmation step and keep fiction separate.</p><p><a href="checking-log.html">Actual run and reflection</a> · <a href="AGENTS.md">Editorial rules</a></p>'''
save('workflow.html',shell('Workflow',workflow))

