deck=''
for s in slides:
 body='<div class="bilingual"><div class="body" lang="zh-Hant"><p class="language-label">繁體中文</p>'+s['body']+'</div><div class="body" lang="en"><p class="language-label">English</p>'+s['body_en']+'</div></div>'
 if s['visual']: body+='<div class="shared-visual">'+s['visual']+'</div>'
 deck+=f'<section class="slide{" active" if s["number"]==1 else ""}" id="slide-{s["number"]}" aria-label="投影片 {s["number"]}"><p class="eyebrow">{s["number"]:02d} / 18 · {"附錄 / Appendix" if s["number"]>15 else "教學 / Lesson"}</p><h1>{s["title"]}<span class="english-title" lang="en">{s["title_en"]}</span></h1>{body}'+(f'<aside class="note"><div lang="zh-Hant">{s["note"]}</div><div lang="en">{s["note_en"]}</div></aside>' if s['note'] else '')+f'<div class="refs"><a href="{s["wiki"]}.html">Wiki：{s["wiki"]}</a></div>'+refs(s['evidence'])+'</section>'
