if checkfile.exists():
 r=json.loads(checkfile.read_text(encoding='utf-8')); summary=f'<p>Last actual check: {r["status"]}. {len(r["checks"])} checks. <a href="data/check-results.json">Read counts and any errors.</a></p>'
else: summary='<p>Not run yet. See the result file after executing the checker.</p>'
browserfile=ROOT/'data/browser-review.html'
browser=browserfile.read_text(encoding='utf-8') if browserfile.exists() else '<p>Browser validation has not yet been performed.</p>'
log=log.replace('<h2>Reproducible structural check</h2>','<h2>Implementation issues found and corrected</h2><p>T01: The first link check ran before its output report existed and flagged that report link. The failed report is preserved in <a href="data/check-run-01.json">check-run-01.json</a>. The report was generated, then links were rechecked.</p><p>T02: Browser review found broken images although the filenames existed. The first museum image endpoint returned HTML bytes. Replacement downloads from the official collection API returned image/jpeg and decoded in the browser. A JPEG signature check was added before publication.</p><p>T03: Mobile navigation wrapped its button text vertically. Fixed button shrinking and simplified the narrow navigation bar, then rechecked.</p><h2>Reproducible structural check</h2>')
save('checking-log.html',shell('Checking log',log.replace('CHECK_SUMMARY',summary).replace('BROWSER_RESULTS',browser)))
save('README.md','# Persian Rug Motifs\n\nEnglish linked LLM-assisted Wiki and Traditional Chinese 18-slide HTML lesson. Open index.html or presentation.html. No install, secret or live API required.\n\nBuild: `python scripts/build.py`\nCheck: `python scripts/check.py`\n\nRead AGENTS.md for editorial rules. data/sources.json contains ten public-source notes; data/wiki.json contains labelled claims; data/slides.json records slide-to-Wiki-to-evidence mapping. Original museum text is not republished. Museum photographs retain their stated rights. Source notes are concise paraphrases. Chinese is unreviewed.\n')
print('Built 10 source notes, 7 topic pages, registers, workflow, log and 18-slide lesson.')

# Bilingual presentation styling and interface labels.
with (ROOT/'style.css').open('a',encoding='utf-8') as f:
 f.write('''\n.english-title{display:block;font-family:system-ui,sans-serif;font-size:.55em;line-height:1.35;margin-top:12px;color:#5f635d}.bilingual{display:grid;grid-template-columns:1fr 1fr;gap:36px}.bilingual .body{font-size:20px}.bilingual .body+ .body{border-left:1px solid var(--line);padding-left:30px}.language-label{font-size:12px!important;letter-spacing:.12em;color:var(--red)}.shared-visual{margin:24px auto;max-width:100%}.shared-visual>figure,.shared-visual>.diagram{max-width:640px;margin:auto}.shared-visual .art{height:280px}.shared-visual>.diagram svg{height:210px}.slide .note{font-size:16px}.note [lang=en]{margin-top:10px}.slide .compare svg{height:110px}@media(max-width:720px){.bilingual{grid-template-columns:1fr;gap:15px}.bilingual .body+ .body{border-left:0;border-top:1px solid var(--line);padding:18px 0 0}.bilingual .body{font-size:18px}.decknav button{font-size:12px;padding:10px 6px}.english-title{font-size:.6em}}\n''')
presentation=(ROOT/'presentation.html').read_text(encoding='utf-8')
presentation=presentation.replace('>上一張</button>','>上一張 / Prev</button>').replace('>下一張</button>','>下一張 / Next</button>').replace('>英文 Wiki</a>','>English Wiki</a>').replace('>來源</a>','>來源 / Sources</a>').replace('>檢查紀錄</a>','>紀錄 / Log</a>').replace('· 教學簡報</title>','· Bilingual lesson</title>')
for s in slides:
 presentation=presentation.replace(f'>{s["number"]}. {s["title"]}</option>',f'>{s["number"]}. {s["title"]} / {s["title_en"]}</option>')
save('presentation.html',presentation)
for name in ['index.html','README.md','workflow.html']:
 text=(ROOT/name).read_text(encoding='utf-8').replace('Start the Traditional Chinese lesson','Start the bilingual lesson').replace('Traditional Chinese 18-slide','Traditional Chinese and English 18-slide').replace('Chinese teaching slides','Bilingual teaching slides')
 save(name,text)
